<script setup>import {ref} from 'vue';import e from '../data/report-evidence.json';const view=ref('personal');const url='https://github.com/M1hono/capstone-demo-ppt/commit/'</script>
<template><div class="stack"><div class="tabs"><button :aria-pressed="view==='personal'" @click.stop="view='personal'">XingTang Chen</button><button :aria-pressed="view==='team'" @click.stop="view='team'">All nine members</button></div><template v-if="view==='personal'"><div class="split wide-left grow"><div class="col"><h2>Technical presentation engineering</h2><p class="statement">Implemented the visual and interactive system used to explain the research.</p><div class="chips"><span>Slidev / Vue</span><span>Three.js</span><span>Real FiveK assets</span><span>Browser QA</span></div><p class="small">Report: PPT production, report assistance and recorded minute-taking. Research-content review by Lunyan Wang.</p></div><div class="col"><article v-for="item in e.personalEvidence" :key="item.hash" class="rule"><h3>{{item.title}} <a :href="url+item.hash" target="_blank" rel="noopener" class="small">{{item.hash}}</a></h3><p class="small muted">{{item.description}}</p></article></div></div><p class="note">Evidence supports presentation, communication and delivery contributions. Model design, training and research results remain attributed to the team’s model-development work.</p></template><table v-else class="evidence-table compact"><thead><tr><th>Member</th><th>Supported contribution</th><th>Evidence status</th></tr></thead><tbody><tr v-for="member in e.contributions" :key="member.name" :class="{highlight:member.name==='XingTang Chen'}"><td style="white-space:nowrap">{{member.name}}</td><td>{{member.work}}</td><td>{{member.status}}</td></tr></tbody></table></div></template>
